analysisCards: (function (self) {
        var base = self._mcAnaCards || null;   // marca do remendo anterior: this._mcAnaCards ||
        if (!base) return null;
        // ROTULOS no idioma de quem le , o site e EN por padrao mas tem 8 idiomas.
        var _lg2 = (function () { try { return (document.documentElement.lang || 'en').toLowerCase().slice(0, 2) || 'en'; } catch (e) { return 'en'; } })();
        var RT = ({
          pt: ['Eventos de hoje:', 'Eventos de alto impacto hoje'],
          es: ['Eventos de hoy:', 'Eventos de alto impacto hoy'],
          it: ['Eventi di oggi:', 'Eventi ad alto impatto oggi'],
          fr: ["Evenements du jour :", 'Evenements a fort impact aujourdhui'],
          de: ['Termine heute:', 'Termine mit hoher Wirkung heute'],
          ar: ['أحداث اليوم:', 'أحداث عالية التأثير اليوم'],
          id: ['Agenda hari ini:', 'Agenda berdampak tinggi hari ini']
        })[_lg2] || ["Today's events:", 'High-impact events today'];
        // MESMA fonte do calendario da home. Sem calendario carregado, o bloco
        // simplesmente nao aparece , nunca inventa evento.
        var cal = (self.calData || []).filter(function (e) { return e.day === 'today'; });
        var altos = cal.filter(function (e) { return e.impact === 'high'; });
        var CCY = 'flex-shrink:0;font-size:10px;font-weight:800;letter-spacing:0.04em;padding:2px 7px;border-radius:5px;background:rgba(255,255,255,0.07);color:#c4ccd2;';
        var evs = altos.slice(0, 8).map(function (e) {
          return { hora: e.time || '', ccy: e.ccy || '', ccyStyle: CCY, nome: e.name || '',
                   previsao: e.forecast ? ('Forecast: ' + e.forecast) : '' };
        });
        // frase corrida com hora + nome + previsao, igual ao site atual
        var texto = cal.slice(0, 6).map(function (e) {
          return '[' + (e.time || '') + '] ' + (e.ccy || '') + ' ' + (e.name || '')
               + (e.forecast ? (' - Forecast: ' + e.forecast) : '')
               + (e.previous ? (' Prev: ' + e.previous) : '') + '.';
        }).join(' ');
        return base.map(function (c) {
          // bolinhas de confianca: 5 pontos, cheios conforme a forca do vies
          var b = String(c.bias || '').toUpperCase();
          var cheios = b.indexOf('NEUTRAL') > -1 ? 3 : (b ? 4 : 0);
          var cor = b.indexOf('BULL') > -1 ? '#34d399' : (b.indexOf('BEAR') > -1 ? '#f87171' : '#fbbf24');
          var dots = '';
          for (var i = 0; i < 5; i++) dots += (i < cheios ? '●' : '○');
          return Object.assign({}, c, {
            dots: dots,
            dotsStyle: 'font-size:9px;letter-spacing:3px;color:' + cor + ';',
            temEventos: evs.length > 0,
            rotEventos: RT[0], rotAlto: RT[1],
            eventosTexto: texto, eventos: evs
          });
        });
      })(this) || [
